// === Tab: mySketch.js ===
// Reading a very good tutorial from Juan Carlos Ponce Campuzano (jcponcemath) on https://complex-analysis.com/,
// I found a very nice animation especifically on page:
// https://complex-analysis.com/content/linear_fractional_transformations.html
// As there was no code, I took the challenge to try to write a shader for it.
// Not perfect, I still have to work on it.
// It's really worthwhile reading his work. There's more on https://www.jcponce.com/

let shaderProgram;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	shaderProgram = createShader(`
      attribute vec3 aPosition;
      void main() {
        gl_Position = vec4(aPosition, 1.0);
      }
    `, `
      precision mediump float;
      uniform vec2 iResolution;
      uniform float iTime;
      #define PI 3.14159265359
      // -------- Complex math --------
      vec2 cmul(vec2 z, vec2 w){
          return vec2(z.x*w.x - z.y*w.y, z.x*w.y + z.y*w.x);
      }
      vec2 cdiv(vec2 z, vec2 w){
          return vec2(z.x*w.x + z.y*w.y, -z.x*w.y + z.y*w.x) / dot(w,w);
      }
      vec2 applyMobius(vec2 z){
          vec2 A = vec2(-1.0,0.0);
          vec2 B = vec2( 1.0,0.0);
          vec2 C = vec2(-1.0,0.0);
          vec2 D = vec2(-1.0,0.0);
          return cdiv(cmul(A,z)+B, cmul(C,z)+D);
      }
      // -------- 2D rotation (clockwise) --------
      vec2 rotate2D(vec2 uv, float angle){
          float c = cos(angle);
          float s = sin(angle);
          return vec2(c * uv.x - s * uv.y, s * uv.x + c * uv.y);
      }
      // -------- Scene SDF --------
      float map(vec3 p){
        float plane = p.y;
        vec3 spherePos = vec3(0.0, 1.2, 0.0);
        float sphere = length(p - spherePos) - 1.2;
        return min(plane, sphere);
      }
      // -------- Normal --------
      vec3 getNormal(vec3 p){
          float e = 0.001;
          return normalize(vec3(
              map(p + vec3(e,0,0)) - map(p - vec3(e,0,0)),
              map(p + vec3(0,e,0)) - map(p - vec3(0,e,0)),
              map(p + vec3(0,0,e)) - map(p - vec3(0,0,e))
          ));
      }
      // -------- Soft Shadow --------
      float softShadow(vec3 ro, vec3 rd, float mint, float maxt){
        float res = 1.0;
        float t = mint;
        for(int i = 0; i < 32; i++){
          float h = map(ro + rd * t);
          if(h < 0.001) return 0.0;
          res = min(res, 8.0 * h / t);
          t += h;
          if(t > maxt) break;
        }
        return res;
      }
      // -------- Möbius checker (only for plane) -------- Thanks for helping here @Shane !
      float mobiusChecker(vec2 uv){
      vec2 z = applyMobius(uv);
      float r = log(length(z)+1e-4);

      // Angular component -- Using a number close to one "6/TAU"
      // to allow for correct modulo wrapping,
      float a = atan(z.y, z.x)*6./6.2831853;

      float t = iTime * 0.2;
      a += t;
      vec2 gridUV = vec2(r, a);
      vec2 g = floor(gridUV * 4.0);
      return mod(g.x + g.y, 2.0);
      }
      // -------- Axis rotation --------
      vec3 rotateAroundAxis(vec3 p, vec3 axis, float angle){
          axis = normalize(axis);
          float c = cos(angle);
          float s = sin(angle);
          return p * c + cross(axis, p) * s + axis * dot(axis, p) * (1.0 - c);
      }
      // -------- Main --------
      void main(){
        vec2 uv = (gl_FragCoord.xy - iResolution.xy)/iResolution.y;
        // -------- CAMERA --------
        vec3 ro = vec3(0.0, 3.5, 4.0);

        float sceneShiftY = 0.7;
        vec3 ta = vec3(0.0, 0.6 - sceneShiftY, 0.0);

        vec3 f = normalize(ta - ro);
        vec3 r = normalize(cross(vec3(0,1,0), f));
        vec3 u = cross(f, r);
        vec3 rd = normalize(uv.x * r + uv.y * u + 1.4 * f);
        // -------- RAYMARCH --------
        float t = 0.0;
        float d;
        for(int i=0; i<100; i++){
          vec3 p = ro + rd * t;
          d = map(p);
          if(d < 0.001 || t > 30.0) break;
          t += d;
        }
        vec3 col = vec3(0.05);
        if(t < 30.0){
          vec3 p = ro + rd * t;
          vec3 n = getNormal(p);

          // -------- LIGHTS --------
          vec3 keyLight = normalize(vec3(-2.5, 2.0, 0.3));   // strong right-top
          vec3 fillLight = normalize(vec3(1.8, 1.5, 1.0));   // soft left-top

          // -------- PATTERN SCALE --------
          float patternScale = 0.5;

          // -------- PLANE --------
          if(abs(p.y) < 0.01){
            vec2 planeUV = p.xz * patternScale;
            float rotationAngle = 0.40;
            planeUV = rotate2D(planeUV, rotationAngle);
            float c = mobiusChecker(planeUV);
            col = mix(vec3(0.1), vec3(0.9), c);

            // -------- SHADOW (only cast by key light) --------
            vec3 shadowOrigin = p + vec3(0.0, 0.02, 0.0);
            float shaKey = softShadow(shadowOrigin, keyLight, 0.01, 30.0);

            // Key light gets full shadow (this creates the soft shadow on the left)
            float diffKey = max(dot(n, keyLight), 0.0) * shaKey;
            float diffFill = max(dot(n, fillLight), 0.0) * 0.75;

            float shadowedDiff = diffKey + diffFill;
            shadowedDiff = max(shadowedDiff, 0.15);

            col *= shadowedDiff;
          }
          // -------- SPHERE --------
          else {
            vec3 center = vec3(0.0, 1.2, 0.0);
            vec3 sp = p - center;

            sp = vec3(sp.z, sp.x, -sp.y);

            float tilt = 0.3;
            mat2 rotTilt = mat2(cos(tilt), -sin(tilt), sin(tilt), cos(tilt));
            sp.xy = rotTilt * sp.xy;

            float poleAlignAngle = 0.40;
            sp = rotateAroundAxis(sp, vec3(0.0, 1.0, 0.0), poleAlignAngle);

            float radius = 1.2;
            float speed = 1.2;
            float angle = iTime/4.0 * speed / radius;
            vec3 axis = vec3(0.0, 1.0, 0.0);
            sp = rotateAroundAxis(sp, axis, -angle);

            vec3 nsp = normalize(sp);
            float u = atan(nsp.z, nsp.x);
            float v = acos(nsp.y);
            float c = mod(floor(u*4.0) + floor(v*4.0), 2.0);

            col = mix(vec3(0.1), vec3(0.9), c);

            float diffKey = max(dot(n, keyLight), 0.0);
            float diffFill = max(dot(n, fillLight), 0.0) * 0.75;
            float diff = diffKey + diffFill;
            diff = max(diff, 0.15);
            col *= diff;
          }
        }
        gl_FragColor = vec4(col,1.0);
      }
    `);
	shader(shaderProgram);
}

function draw() {
	shaderProgram.setUniform('iResolution', [width, height]);
	shaderProgram.setUniform('iTime', millis() / 1000.0);
	quad(-1, -1, -1, 1, 1, 1, 1, -1);
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
